ALTER TABLE orders ADD COLUMN model_id INTEGER;
CREATE TABLE IF NOT EXISTS models(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,cat TEXT,mat TEXT,hours REAL,who TEXT,descr TEXT,lay TEXT,inf TEXT,walls INTEGER,sup TEXT,tags TEXT,col TEXT,imgs TEXT,stls TEXT,views INTEGER DEFAULT 0,created INTEGER);
CREATE TABLE IF NOT EXISTS model_likes(model_id INTEGER NOT NULL,user_id INTEGER NOT NULL,PRIMARY KEY(model_id,user_id));
